1	import homeright from '../src/components/hoemright.vue';
2	import typewriter from './components/typewriter.vue';
3	import tab1 from './components/tabs/tab1.vue';
4	import tab2 from './components/tabs/tab2.vue';
5	import tab3 from './components/tabs/tab3.vue';
6	import loader from './components/loader.vue';
7	import polarchart from './components/polarchart.vue';
8	import config from './config.js';
9	import { getCookie } from './utils/cookieUtils.js';
10	import { setMeta,getFormattedTime,getFormattedDate,dataConsole } from './utils/common.js';
11	import { useDisplay } from 'vuetify'
12	
13	export default {
14	  components: {
15	    tab1,tab2,tab3,loader,homeright,typewriter,polarchart
16	  },
17	  setup() {
18	    const { xs,sm,md } = useDisplay();
19	    return { xs,sm,md };
20	  },
21	  data() {
22	    return {
23	      isloading:false,
24	      isClearScreen: false,
25	      formattedTime:"",
26	      formattedDate:"",
27	      configdata: config,
28	      dialog1: false,
29	      dialog2: false,
30	      personalizedtags: null,
31	      videosrc: '',
32	      ismusicplayer: false,
33	      isPlaying:false,
34	      playlistIndex: 0,
35	      audioLoading: false,
36	      musicinfo: null,
37	      musicinfoLoading:false,
38	      lyrics:{},
39	      socialPlatformIcons: null,
40	      isExpanded: false,
41	      stackicons:[
42	        {icon:"mdi-vuejs",color:"green", model: false,tip: 'vue'},
43	        {icon:"mdi-language-javascript",color:"#CAD300", model: false,tip: 'javascript'},
44	        {icon:"mdi-language-css3",color:"blue", model: false,tip: 'css'},
45	        {icon:"mdi-language-html5",color:"red", model: false,tip: 'html'},
46	        {icon:"$vuetify",color:"#1697F6", model: false,tip: 'vuetify'},
47	      ],
48	      projectcards:null,
49	      tab: null,
50	      tabs: [
51	        {
52	          icon: 'mdi-pencil-plus',
53	          text: '样式预览',
54	          value: 'tab-1',
55	          component: "tab1",
56	        },
57	        {
58	          icon: 'mdi-wallpaper',
59	          text: '背景预览',
60	          value: 'tab-2',
61	          component: "tab2",
62	        },
63	        {
64	          icon: 'mdi-music-circle-outline',
65	          text: '音乐播放',
66	          value: 'tab-3',
67	          component: "tab3",
68	        },
69	      ],
70	
71	    };
72	  },
73	  async mounted() {
74	    if(import.meta.env.VITE_CONFIG){
75	      this.configdata = JSON.parse(import.meta.env.VITE_CONFIG);
76	    }
77	    this.projectcards = this.configdata.projectcards;this.socialPlatformIcons = this.configdata.socialPlatformIcons;
78	    this.personalizedtags = this.configdata.tags;
79	    this.isloading = true;
80	    let imageurl = "";
81	    this.dataConsole();
82	    this.setMeta(this.configdata.metaData.title,this.configdata.metaData.description,this.configdata.metaData.keywords,this.configdata.metaData.icon);
83	    
84	    imageurl = this.setMainProperty(imageurl);
85	
86	    //异步等待背景壁纸包括视频壁纸加载完成后再显示页面
87	    const loadImage = () => {
88	        const imageUrls = [
89	          config.avatar,
90	          ...config.projectcards.map(item => item.img)
91	        ];
92	        return new Promise((resolve, reject) => {
93	          const imagePromises = imageUrls.map((url) => {
94	            return new Promise((resolve, reject) => {
95	                const imgs = new Image();
96	                imgs.src = url;
97	                imgs.onload = () => resolve();
98	                imgs.onerror = (err) => reject(err);
99	            });
100	          })
101	
102	          // 设置超时机制：2.5秒
103	          const timeoutPromise = new Promise((resolve) => {
104	            setTimeout(() => {
105	              resolve();
106	            }, 2500);
107	          });
108	          
109	          // 等待所有图片加载完成或超时
110	          Promise.race([Promise.all(imagePromises), timeoutPromise]).then(()=>{
111	            if(imageurl){
112	              const img = new Image();
113	              img.src = imageurl;
114	              // resolve() 函数通将一个 Promise 对象从未完成状态转变为已完成状态
115	              img.onload = () => {resolve();};
116	              img.onerror = (err) => {reject(err);};
117	            }else{
118	              const video = this.$refs.VdPlayer;
119	              video.onloadedmetadata = () => {
120	                setTimeout(() => {
121	                }, "200");  
122	                resolve();
123	              };
124	              video.onerror = (err) => {resolve();};
125	            }
126	          })
127	        });
128	     };
129	
130	    loadImage().then(() => {
131	        this.formattedTime =  this.getFormattedTime(new Date());
132	        this.formattedDate =  this.getFormattedDate(new Date());
133	        setTimeout(() => {
134	          this.isloading = false;
135	        }, "500");          
136	      }).catch((err) => {
137	        console.error('壁纸加载失败:', err);
138	        setTimeout(() => {
139	          this.isloading = false;
140	        }, "100");  
141	      });
142	 
143	      setInterval(() => {
144	        this.formattedTime =  this.getFormattedTime(new Date()) ;
145	      }, 1000);
146	
147	      await this.getMusicInfo();  //获取音乐数据
148	      this.setupAudioListener();  //设置 ended 事件监听器，当歌曲播放结束时自动调用 nextTrack 方法。
149	  },
150	
151	  beforeDestroy() {     //在组件销毁前移除事件监听器，防止内存泄漏。
152	    this.$refs.audioPlayer.removeEventListener('ended',  this.nextTrack);
153	  },
154	
155	  watch:{
156	    isClearScreen(val){
157	      if(!this.videosrc){
158	        return
159	      }
160	      if(val){
161	        this.$refs.VdPlayer.style.zIndex = 0; 
162	        this.$refs.VdPlayer.controls = true;
163	      }else{
164	        this.$refs.VdPlayer.style.zIndex = -100; 
165	        this.$refs.VdPlayer.controls = false;
166	      }
167	    },
168	    audioLoading(val){
169	      this.isPlaying = !val;
170	    }
171	
172	  //若弹出框使得页面播放卡顿，可以先停止背景播放
173	  //   dialog1(val){
174	  //     if(val){
175	  //       this.$refs.VdPlayer.pause();
176	  //     }else{
177	  //       this.$refs.VdPlayer.play();
178	  //     }
179	  //  }
180	  },
181	
182	  computed: {
183	    currentSong() {
184	      return this.musicinfo[this.playlistIndex];
185	    },
186	    audioPlayer() {
187	      return this.$refs.audioPlayer;
188	    }
189	  },
190	  
191	  methods: {
192	    getCookie,setMeta,getFormattedTime,getFormattedDate,dataConsole,
193	
