195	      const root = document.documentElement;
196	      let leleodata = this.getCookie("leleodata");
197	      if(leleodata){
198	        root.style.setProperty('--leleo-welcomtitle-color', `${leleodata.color.welcometitlecolor}`);
199	        root.style.setProperty('--leleo-vcard-color', `${leleodata.color.themecolor}`);
200	        root.style.setProperty('--leleo-brightness', `${leleodata.brightness}%`);
201	        root.style.setProperty('--leleo-blur', `${leleodata.blur}px`); 
202	      }else{
203	        root.style.setProperty('--leleo-welcomtitle-color', `${this.configdata.color.welcometitlecolor}`);
204	        root.style.setProperty('--leleo-vcard-color', `${this.configdata.color.themecolor}`);  
205	        root.style.setProperty('--leleo-brightness', `${this.configdata.brightness}%`);  
206	        root.style.setProperty('--leleo-blur', `${this.configdata.blur}px`);
