const STORAGE_KEY = 'leleoConfig';

export function saveConfigToStorage(config) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(config));
  } catch (e) {
    console.error('保存配置到 localStorage 失败:', e);
  }
}

export function loadConfigFromStorage() {
  try {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : null;
  } catch (e) {
    console.error('从 localStorage 读取配置失败:', e);
    return null;
  }
}

export function removeConfigFromStorage() {
  try {
    localStorage.removeItem(STORAGE_KEY);
  } catch (e) {
    console.error('清除 localStorage 配置失败:', e);
  }
}

